reference_solution:
def maximum_custom_substring_cost(s,chars,vals):
    custom=dict(zip(chars,vals));best=current=0
    for char in s:
        value=custom.get(char,ord(char)-ord('a')+1)
        current=max(0,current+value);best=max(best,current)
    return best

